import { ROUTES } from '@/shared/config';
import FilterPillGroup from '@/components/marketing/FilterPillGroup/FilterPillGroup';
import Pagination from '@/components/common/Pagination/Pagination';
import usePaginatedSlice from '@/shared/hooks/usePaginatedSlice';
import {
  PHOTOGRAPHER_STORE_CATEGORIES,
  PHOTOGRAPHER_STORE_PAGE_SIZE,
  getPhotographerStoreProduct,
} from '@/portals/public/photographer/data/photographerProfileData';

const StoreProductCard = memo(({ product, onView }) => {
  const { t } = useTranslation();
  const navigate = useNavigate();

  return (
    <article className="overflow-hidden rounded-[14px] border border-[#e8eaef] bg-white shadow-[0_1px_2px_rgba(15,23,42,0.04)]">
      <div className="relative aspect-4/3 overflow-hidden bg-[#f3f4f6]">
        <img src={product.image} alt={product.title} className="size-full object-cover" loading="lazy" />
        <span className="absolute left-2.5 top-2.5 rounded-full bg-[#111827]/85 px-2 py-1 text-[10px] font-bold tracking-[0.06em] text-white">
          {t(product.badgeKey)}
        </span>
      </div>
      <div className="flex flex-col gap-3 p-3.5 sm:p-4">
        <div>
          <h3 className="line-clamp-2 text-[14px] font-bold leading-5 text-[#111827]">{product.title}</h3>
          <p className="mt-1.5 line-clamp-2 text-[12px] leading-4 text-[#6b7280]">{product.description}</p>
        </div>
        <div className="mt-auto flex flex-wrap items-center justify-between gap-2">
          <p className="text-[16px] font-bold text-[#111827]">{product.price}</p>
          <div className="flex items-center gap-1.5">
            <button
              type="button"
              onClick={() => onView(product.id)}
              className="inline-flex h-8 cursor-pointer items-center rounded-lg bg-[#4048cd] px-2.5 text-[12px] font-semibold text-white transition hover:bg-[#343bb0]"
            >
              {t('photographerProfile.store.viewProduct')}
            </button>
            <button
              type="button"
              onClick={() => navigate(ROUTES.PHOTOGRAPHER_STORE_CHECKOUT, { state: { product } })}
              className="inline-flex h-8 cursor-pointer items-center rounded-lg bg-[#ee1c25] px-2.5 text-[12px] font-semibold text-white transition hover:bg-[#d01820]"
            >
              {t('photographerProfile.store.buyNow')}
            </button>
          </div>
        </div>
      </div>
    </article>
  );
});
StoreProductCard.displayName = 'StoreProductCard';

const StoreProductDetail = memo(({ product, onBack }) => {
  const { t } = useTranslation();
  const navigate = useNavigate();
  const [sizeId, setSizeId] = useState(product.sizes?.[0]?.id || '');
  const [qty, setQty] = useState(1);
  const [activeImage, setActiveImage] = useState(product.gallery?.[0] || product.image);

  return (
    <div className="mt-6 sm:mt-8">
      <button
        type="button"
        onClick={onBack}
        className="mb-4 inline-flex cursor-pointer items-center gap-1.5 text-[13px] font-semibold text-[#6b7280] transition hover:text-[#4048cd]"
      >
        <ArrowLeft size={14} aria-hidden="true" />
        {t('photographerProfile.store.back')}
      </button>

      <div className="grid grid-cols-1 gap-6 lg:grid-cols-2 lg:gap-10">
        <div>
          <div className="overflow-hidden rounded-[14px] bg-[#f3f4f6]">
            <img src={activeImage} alt={product.title} className="aspect-4/3 w-full object-cover" />
          </div>
          {product.gallery?.length > 1 ? (
            <div className="mt-3 grid grid-cols-4 gap-2.5">
              {product.gallery.map((src) => (
                <button
                  key={src}
                  type="button"
                  onClick={() => setActiveImage(src)}
                  className={`overflow-hidden rounded-[10px] border-2 ${
                    activeImage === src ? 'border-[#4048cd]' : 'border-transparent'
                  }`}
                >
                  <img src={src} alt="" className="aspect-square w-full object-cover" />
                </button>
              ))}
            </div>
          ) : null}
        </div>

        <div>
          <h2 className="text-[24px] font-bold leading-snug text-[#111827] sm:text-[28px]">
            {product.title}
          </h2>
          <div className="mt-3 space-y-3 text-[14px] leading-6 text-[#6b7280]">
            {product.detailParagraphs.map((paragraph) => (
              <p key={paragraph.slice(0, 28)}>{paragraph}</p>
            ))}
          </div>
          <p className="mt-5 text-[28px] font-bold text-[#4048cd]">{product.price}</p>

          {product.sizes?.length ? (
            <div className="mt-5">
              <p className="text-[13px] font-semibold text-[#374151]">
                {t('photographerProfile.store.selectSize')}
              </p>
              <div className="mt-2.5 flex flex-wrap gap-2">
                {product.sizes.map((size) => (
                  <button
                    key={size.id}
                    type="button"
                    onClick={() => setSizeId(size.id)}
                    className={`inline-flex h-9 cursor-pointer items-center rounded-full border px-3.5 text-[12px] font-semibold transition ${
                      sizeId === size.id
                        ? 'border-[#4048cd] bg-[#4048cd] text-white'
                        : 'border-[#dbe0ea] bg-white text-[#374151] hover:border-[#4048cd]/40'
                    }`}
                  >
                    {size.label}
                  </button>
                ))}
              </div>
            </div>
          ) : null}

          <div className="mt-6 flex flex-wrap items-center gap-3">
            <div className="inline-flex h-11 items-center rounded-[10px] border border-[#e5e7eb] bg-white">
              <button
                type="button"
                aria-label={t('photographerProfile.store.decreaseQty')}
                onClick={() => setQty((value) => Math.max(1, value - 1))}
                className="inline-flex size-11 cursor-pointer items-center justify-center text-[#6b7280]"
              >
                <Minus size={16} aria-hidden="true" />
              </button>
              <span className="min-w-8 text-center text-[14px] font-bold text-[#111827]">
                {String(qty).padStart(2, '0')}
              </span>
              <button
                type="button"
                aria-label={t('photographerProfile.store.increaseQty')}
                onClick={() => setQty((value) => value + 1)}
                className="inline-flex size-11 cursor-pointer items-center justify-center text-[#6b7280]"
              >
                <Plus size={16} aria-hidden="true" />
              </button>
            </div>
            <button
              type="button"
              onClick={() => navigate(ROUTES.PHOTOGRAPHER_STORE_CHECKOUT, { state: { product: { ...product, qty, sizeId } } })}
              className="inline-flex h-11 flex-1 cursor-pointer items-center justify-center gap-2 rounded-[10px] bg-[#ee1c25] px-5 text-[14px] font-bold text-white transition hover:bg-[#d01820] sm:min-w-55"
            >
              {t('photographerProfile.store.buyNow')}
              <ShoppingCart size={16} aria-hidden="true" />
            </button>
          </div>
        </div>
      </div>
    </div>
  );
});
StoreProductDetail.displayName = 'StoreProductDetail';

const PhotographerStoreSection = memo(({ products }) => {
  const { t } = useTranslation();
  const [category, setCategory] = useState('all');
  const [selectedId, setSelectedId] = useState(null);

  const selectedProduct = selectedId ? getPhotographerStoreProduct(selectedId) : null;

  const filterItems = useMemo(
    () =>
      PHOTOGRAPHER_STORE_CATEGORIES.map((item) => ({
        id: item.id,
        value: item.id,
        label: t(item.labelKey),
      })),
    [t],
  );

  const filtered = useMemo(() => {
    if (category === 'all') return products;
    return products.filter((product) => product.category === category);
  }, [category, products]);

  const { currentPage, setPage, totalPages, pagedItems } = usePaginatedSlice(
    filtered,
    PHOTOGRAPHER_STORE_PAGE_SIZE,
    [category],
  );

  if (selectedProduct) {
    return <StoreProductDetail product={selectedProduct} onBack={() => setSelectedId(null)} />;
  }

  return (
    <section className="mt-6 sm:mt-8">
      <div className="flex items-center gap-2">
        <ShoppingBag size={22} className="shrink-0 text-[#4048cd]" aria-hidden="true" />
        <h2 className="text-[20px] font-bold text-[#111827] sm:text-[22px]">
          {t('photographerProfile.store.title')}
        </h2>
      </div>
      <p className="mt-1 max-w-2xl text-[14px] leading-6 text-[#6b7280] sm:text-[15px]">
        {t('photographerProfile.store.subtitle')}
      </p>

      <FilterPillGroup
        className="mt-4 lg:justify-start"
        layout="scroll"
        items={filterItems}
        value={category}
        onChange={setCategory}
        ariaLabel={t('photographerProfile.store.filtersAria')}
        renderLabel={(item) => item.label}
      />

      <div className="mt-6 grid gap-5 sm:grid-cols-2 xl:grid-cols-4">
        {pagedItems.map((product) => (
          <StoreProductCard key={product.id} product={product} onView={setSelectedId} />
        ))}
      </div>

      <Pagination
        className="mt-8"
        currentPage={currentPage}
        totalPages={totalPages}
        onPageChange={setPage}
        ariaLabel={t('photographerProfile.store.paginationAria')}
      />
    </section>
  );
});

PhotographerStoreSection.displayName = 'PhotographerStoreSection';

export default PhotographerStoreSection;

import { useCallback, useMemo, useRef, useState } from 'react';
import { useForm } from 'react-hook-form';
import toast from 'react-hot-toast';
import {
  ABOUT_MAX_WORDS,
  DEFAULT_THEME_ID,
  EMPTY_STORY,
  ZODIAC_SIGNS,
  countWords,
  findPromoLinkByCode,
  getSlotsForTheme,
} from '@/portals/public/promo-join/promoJoinData';

const revokePreview = (url) => {
  if (url?.startsWith?.('blob:')) URL.revokeObjectURL(url);
};

export default function usePromoJoin(code) {
  const promoLink = useMemo(() => findPromoLinkByCode(code), [code]);

  const {
    register,
    handleSubmit: hookFormSubmit,
    watch,
    formState: { errors },
  } = useForm({
    defaultValues: {
      fullName: '',
      username: '',
      email: '',
      phone: '',
      country: '',
      paypal: '',
      about: '',
      password: '',
    },
  });

  const [socialLinks, setSocialLinks] = useState(['']);
  const [profilePreview, setProfilePreview] = useState('');
  const [coverPreview, setCoverPreview] = useState('');
  const [introVideoName, setIntroVideoName] = useState('');
  const [astroSignId, setAstroSignId] = useState('virgo');
  const [astroOpen, setAstroOpen] = useState(false);

  const [themeId, setThemeId] = useState(DEFAULT_THEME_ID);
  const [sixPreviews, setSixPreviews] = useState({});
  const [twelvePreviews, setTwelvePreviews] = useState({});
  const [sixVideos, setSixVideos] = useState([]);
  const [twelveVideos, setTwelveVideos] = useState([]);

  const [sixStory, setSixStory] = useState(EMPTY_STORY);
  const [twelveStory, setTwelveStory] = useState(EMPTY_STORY);
  const [aiCreated, setAiCreated] = useState('');
  const [copyrightOk, setCopyrightOk] = useState(false);
  const [submitting, setSubmitting] = useState(false);
  const [submitted, setSubmitted] = useState(false);

  const profileInputRef = useRef(null);
  const coverInputRef = useRef(null);
  const introVideoRef = useRef(null);
  const sixSlotInputRef = useRef(null);
  const twelveSlotInputRef = useRef(null);
  const sixVideoInputRef = useRef(null);
  const twelveVideoInputRef = useRef(null);
  const activeSixSlotRef = useRef(null);
  const activeTwelveSlotRef = useRef(null);

  const selectedSign = ZODIAC_SIGNS.find((sign) => sign.id === astroSignId) || ZODIAC_SIGNS[5];
  const sixSlots = getSlotsForTheme(themeId);

  const patchSixStory = (field, value) => {
    setSixStory((current) => ({ ...current, [field]: value }));
  };

  const patchTwelveStory = (field, value) => {
    setTwelveStory((current) => ({ ...current, [field]: value }));
  };

  const handleSocialChange = (index, value) => {
    setSocialLinks((current) => current.map((item, i) => (i === index ? value : item)));
  };

  const handleAddSocial = () => {
    setSocialLinks((current) => [...current, '']);
  };

  const readImagePreview = (file, onReady) => {
    if (!file || !file.type.startsWith('image/')) return;
    const url = URL.createObjectURL(file);
    onReady(url);
  };

  const handleProfileChange = (event) => {
    const file = event.target.files?.[0];
    readImagePreview(file, (url) => {
      setProfilePreview((prev) => {
        revokePreview(prev);
        return url;
      });
    });
    event.target.value = '';
  };

  const handleCoverChange = (event) => {
    const file = event.target.files?.[0];
    readImagePreview(file, (url) => {
      setCoverPreview((prev) => {
        revokePreview(prev);
        return url;
      });
    });
    event.target.value = '';
  };

  const handleIntroVideoChange = (event) => {
    const file = event.target.files?.[0];
    if (!file) return;
    setIntroVideoName(file.name);
    event.target.value = '';
  };

  const handleSixSlotPick = (slotId) => {
    activeSixSlotRef.current = slotId;
    sixSlotInputRef.current?.click();
  };

  const handleTwelveSlotPick = (slotId) => {
    activeTwelveSlotRef.current = slotId;
    twelveSlotInputRef.current?.click();
  };

  const handleSixSlotFile = (event) => {
    const file = event.target.files?.[0];
    const slotId = activeSixSlotRef.current;
    if (!file || !slotId) return;
    const url = URL.createObjectURL(file);
    setSixPreviews((current) => {
      revokePreview(current[slotId]);
      return { ...current, [slotId]: url };
    });
    event.target.value = '';
  };

  const handleTwelveSlotFile = (event) => {
    const file = event.target.files?.[0];
    const slotId = activeTwelveSlotRef.current;
    if (!file || !slotId) return;
    const url = URL.createObjectURL(file);
    setTwelvePreviews((current) => {
      revokePreview(current[slotId]);
      return { ...current, [slotId]: url };
    });
    event.target.value = '';
  };

  const handleSixVideos = (event) => {
    const files = Array.from(event.target.files || []);
    if (!files.length) return;
    setSixVideos((current) => [...current, ...files.map((file) => file.name)]);
    event.target.value = '';
  };

  const handleTwelveVideos = (event) => {
    const files = Array.from(event.target.files || []);
    if (!files.length) return;
    setTwelveVideos((current) => [...current, ...files.map((file) => file.name)]);
    event.target.value = '';
  };

  const validateOtherFields = (t, data) => {
    if (countWords(data.about) > ABOUT_MAX_WORDS) return t('promoJoin.errors.about');
    if (!copyrightOk) return t('promoJoin.errors.copyright');
    return null;
  };

  const onSubmitForm = async (data, t) => {
    const error = validateOtherFields(t, data);
    if (error) {
      toast.error(error);
      return;
    }
    setSubmitting(true);
    await new Promise((resolve) => window.setTimeout(resolve, 700));
    setSubmitting(false);
    setSubmitted(true);
    toast.success(t('promoJoin.success'));
  };

  const handleSubmit = (t) => hookFormSubmit((data) => onSubmitForm(data, t));

  return {
    code,
    promoLink,
    register,
    handleSubmit,
    errors,
    socialLinks,
    profilePreview,
    coverPreview,
    introVideoName,
    astroSignId,
    astroOpen,
    selectedSign,
    themeId,
    sixSlots,
    sixPreviews,
    twelvePreviews,
    sixVideos,
    twelveVideos,
    sixStory,
    twelveStory,
    aiCreated,
    copyrightOk,
    submitting,
    submitted,
    profileInputRef,
    coverInputRef,
    introVideoRef,
    sixSlotInputRef,
    twelveSlotInputRef,
    sixVideoInputRef,
    twelveVideoInputRef,
    patchSixStory,
    patchTwelveStory,
    handleSocialChange,
    handleAddSocial,
    handleProfileChange,
    handleCoverChange,
    handleIntroVideoChange,
    setAstroSignId,
    setAstroOpen,
    setThemeId,
    handleSixSlotPick,
    handleTwelveSlotPick,
    handleSixSlotFile,
    handleTwelveSlotFile,
    handleSixVideos,
    handleTwelveVideos,
    setAiCreated,
    setCopyrightOk,
  };
}
